content.query:
let ev = customEvents;
let visits = toscalar(ev | where name == "AppOpen" | count);
let visitors = toscalar(ev | where name == "AppOpen" | summarize dcount(user_Id));
let uses = toscalar(ev | where name != "AppOpen" | count);
let users = toscalar(ev | summarize dcount(user_Id));
let zhUsers = toscalar(ev | where tostring(customDimensions.language) == "zh" | summarize dcount(user_Id));
datatable(Order:int, Metric:string, Value:real)[
 1, "Visits", real(null), 2, "Visitors", real(null), 3, "Feature uses", real(null), 4, "Chinese users %", real(null)]
| extend Value = case(Order == 1, todouble(visits), Order == 2, todouble(visitors), Order == 3, todouble(uses),
    iff(users == 0, 0.0, round(100.0 * zhUsers / users, 1)))
| order by Order asc
| project Metric, Value
